<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/lifecycle/pdf.php';require_once __DIR__.'/guide.php';
function nd_owner_guide_pdf(array $ready):string{
 $pdf=new NeuroDocumentPdf();$pdf->AddFont('DejaVu','','DejaVuSans.ttf',true);$pdf->AddFont('DejaVu','B','DejaVuSans-Bold.ttf',true);$pdf->SetMargins(18,32,18);$pdf->SetAutoPageBreak(true,22);$pdf->AliasNbPages();$pdf->AddPage();$heading=function(string $text)use($pdf){if($pdf->GetY()>240)$pdf->AddPage();$pdf->SetFont('DejaVu','B',15);$pdf->MultiCell(0,8,$text,0,'L');$pdf->Ln(3);};$paragraph=function(string $text)use($pdf){$pdf->SetFont('DejaVu','',11);$pdf->MultiCell(0,5.6,$text,0,'L');$pdf->Ln(3);};
 $heading('Что мне сделать сейчас');$paragraph('Руководство владельцу НейроДело. Состояние настроек на момент скачивания: '.(new DateTimeImmutable('now',new DateTimeZone('Europe/Kaliningrad')))->format('d.m.Y H:i').' UTC+2. Это не договор, не чек и не подтверждение завершённой приёмки.');foreach($ready['rows'] as $row)if(!$row['completed']){$heading($row['field']);$paragraph('Страница: https://neurodelo.pro'.$row['page']."\nКто отвечает: ".$row['responsible']."\nОсталось: ".$row['remaining']."\nОткрывает: ".$row['enables']);}
 $heading('Уже выполнено');foreach($ready['rows'] as $row)if($row['completed'])$paragraph($row['field'].' — выполнено. Повторять без причины не требуется.');$heading('Технические сведения и точные вопросы провайдеру');foreach($ready['provider']['verified'] as $fact)$paragraph($fact['fact']."\nГраница подтверждения: ".$fact['scope']."\nИсточник: ".$fact['source']);foreach($ready['provider']['questions'] as $question)$paragraph('Отвечает: '.$question['responsible']."\n".$question['question']."\nПозволит: ".$question['enables']);
 foreach(nd_guide_sections() as $section){$heading($section['title']);foreach($section['paragraphs'] as $text)$paragraph(preg_replace('~(?<![:\w])(/[-a-z0-9/]+\.php(?:\?[-a-z0-9_=&#]+)?)~i','https://neurodelo.pro$1',$text));}
 $screens=['portfolio-editor.png'=>'Портфолио: редактирование и смешанная галерея','payment-settings.png'=>'Настройки оригинального QR','planning.png'=>'Проверка оценок и загрузки'];foreach($screens as $file=>$title){$path=__DIR__.'/screens/'.$file;$info=is_file($path)?@getimagesize($path):false;if(!$info)throw new RuntimeException('owner_guide_screenshot_missing');$pdf->AddPage();$heading($title);$paragraph('Снимок настоящего интерфейса на изолированных синтетических данных. Не является заказом, банковским QR или production-приёмкой.');$width=min(174,174*$info[0]/max($info[0],$info[1]*174/190));$height=$width*$info[1]/$info[0];if($pdf->GetY()+$height>270)$pdf->AddPage();$pdf->Image($path,18,$pdf->GetY(),$width,$height,'PNG');$pdf->SetY(min(268,$pdf->GetY()+$height+4));}
 $bytes=$pdf->Output('S');if(!str_starts_with($bytes,'%PDF-')||!str_contains($bytes,'/FontFile2'))throw new RuntimeException('owner_guide_font_embedding_failed');return $bytes;
}
